import{defaults,evaluate,outcomeFor}from'./engine.js';
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',participants:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',sessions:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M8 14h3 M8 18h6',alerts:'M12 3a6 6 0 0 0-6 6v5l-3 4h18l-3-4V9a6 6 0 0 0-6-6 M10 21h4',rewards:'M3 7h18v14H3z M2 7h20v4H2z M12 7v14 M12 7C4 7 5 1 8 3l4 4 M12 7c8 0 7-6 4-4l-4 4',ladder:'M5 21V3 M19 21V3 M5 7h14 M5 13h14 M5 19h14',reports:'M4 3v18h17 M8 17v-5 M13 17V7 M18 17v-9',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5'};
const svg=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.arrow}"/></svg>`;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+(n/100).toFixed(2),today=new Date().toLocaleDateString('en-GB',{timeZone:'Africa/Harare',weekday:'long',day:'numeric',month:'long',year:'numeric'});
function seed(){const names=['Tinashe','Nyasha','Rudo','Tafadzwa','Chipo','Kuda','Anesu','Vimbai'];return{config:{...defaults},participants:names.map((name,i)=>({code:`PR-HRE-${String(42+i).padStart(4,'0')}`,name,language:['English','chiShona','isiNdebele'][i%3],phase:i<3?'B':'A',week:i<3?8:2,targets:i<3?['MET','AMP','OPI']:['MET','AMP'],streak:[15,8,16,3,5,0,2,4][i],level:[16,9,17,4,6,1,3,5][i],preResetLevel:i===5?7:null,negSinceReset:0,status:'active',credits:i===2?20:0,payout:'airtime',consent:true,research:false,created:'2026-10-01',next:'09:'+String(i*10).padStart(2,'0')})),sessions:[],ledger:[],alerts:[{id:'a1',code:'PR-HRE-0047',level:'red',reason:'Urgent callback requested',summary:'Participant selected “Get help now”. Supervisor review required.',status:'open',time:'12 min ago',notes:''},{id:'a2',code:'PR-HRE-0045',level:'amber',reason:'Strong cravings reported',summary:'Cravings 4/5 in weekly check-in. Requested a conversation.',status:'open',time:'38 min ago',notes:''},{id:'a3',code:'PR-HRE-0048',level:'amber',reason:'Missed previous session',summary:'Reach out with a supportive reminder and agree a new slot.',status:'open',time:'1 hr ago',notes:''}],audit:[],checkins:[],notes:[],activities:[]}}
let db;try{db=JSON.parse(localStorage.getItem('pora-demo-v1'))||seed()}catch{db=seed()}let view='overview',search='',filter='all';const navs=[['overview','Overview'],['participants','Participants'],['sessions','Test sessions'],['alerts','Care alerts'],['rewards','Rewards & payouts'],['ladder','Pora Ladder'],['reports','Pilot reports'],['settings','Programme settings']];
function persist(action,code='programme'){db.audit.unshift({action,code,at:new Date().toISOString()});try{localStorage.setItem('pora-demo-v1',JSON.stringify(db))}catch{toast('Device storage is full. Changes will last for this session only.')}render()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
const btn=(text,action,cls='secondary')=>`<button class="btn ${cls}" data-action="${action}">${text}</button>`;
const pBy=code=>db.participants.find(p=>p.code===code),active=()=>db.participants.filter(p=>p.status==='active'),openAlerts=()=>db.alerts.filter(a=>a.status!=='resolved');
const person=p=>`<div class="person"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div><button class="inline-link" data-profile="${p.code}"><b>${esc(p.name)}</b></button><small>${p.code}</small></div></div>`;
function top(title,desc,action=''){return`<div class="page-top"><div><div class="eyebrow">${view==='overview'?today.toUpperCase():'RECOVERY, ONE STEP AT A TIME'}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function stat(label,value,note,icon){return`<div class="stat"><div class="stat-top">${label}${svg(icon)}</div><div class="stat-num">${value}</div><div class="stat-note">${note}</div></div>`}
function table(headers,rows){return`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">No records here yet.</td></tr>`}</tbody></table></div>`}
function participantRows(list,sessions=false){return list.map(p=>{const done=db.sessions.some(s=>s.code===p.code&&s.date===new Date().toISOString().slice(0,10));return`<tr><td>${person(p)}</td><td>${sessions?p.next:`<span class="pill neutral">Phase ${p.phase}</span>`}</td><td><span class="streak">↗ ${p.streak} sessions</span></td><td><span class="pill ${done?'':'neutral'}">${p.status!=='active'?esc(p.status):done?'Recorded':'Scheduled'}</span></td><td>${p.status==='active'?`<button class="btn ghost" data-test="${p.code}" ${done?'disabled':''}>${done?'Completed':'Record session'} →</button>`:''}</td></tr>`})}
function render(){view=location.hash.slice(1).split('/')[0]||'overview';if(!navs.some(n=>n[0]===view))view='overview';$('#crumb').textContent=navs.find(n=>n[0]===view)[1];$('#nav').innerHTML=navs.map(([k,l])=>`<a class="nav-link ${k===view?'active':''}" href="#${k}" ${k===view?'aria-current="page"':''}>${svg(k)}${l}${k==='alerts'&&openAlerts().length?`<span class="nav-count">${openAlerts().length}</span>`:''}</a>`).join('');const page={overview,participants,sessions,alerts,rewards,ladder,reports,settings}[view];$('#main').innerHTML=page();bind()}
function overview(){const unlocked=active().filter(p=>p.streak>=16).length;return top('A little progress. A brighter future.','Here’s what needs your care at Harare Pora Point today.',btn(svg('plus')+' Enrol participant','enrol',''))+`<div class="stats">${stat('Active participants',active().length,'<strong>Every person, a new possibility</strong>','participants')}${stat('Sessions today',active().length,'Monday & Thursday · Harare time','sessions')}${stat('Needs your attention',openAlerts().length,`${openAlerts().filter(a=>a.level==='red').length} urgent · ${openAlerts().filter(a=>a.level==='amber').length} follow-ups`,'alerts')}${stat('Ladder unlocked',unlocked,'16 consecutive sessions achieved','ladder')}</div><div class="grid"><div><section class="card"><div class="card-head"><div><h2>Today’s sessions</h2><small>Small steps worth showing up for.</small></div><a class="btn ghost" href="#sessions">View all →</a></div>${table(['PARTICIPANT','TIME','PROGRESS','STATUS',''],participantRows(active().slice(0,5),true))}<div class="card-bottom">${db.sessions.filter(s=>s.date===new Date().toISOString().slice(0,10)).length} sessions recorded today · All times UTC+2</div></section><section class="card"><div class="card-head"><div><h2>Progress over time</h2><small>Illustrative pilot attendance · sample data</small></div><span class="pill neutral">Last 8 weeks</span></div><div class="trend"><div class="chart" role="img" aria-label="Illustrative attendance increasing from 48% in week 1 to 87% in week 8">${[48,55,60,58,72,76,82,87].map((n,i)=>`<div class="chart-col"><i style="height:${n}%" title="Week ${i+1}: ${n}%"></i><span>W${i+1}</span></div>`).join('')}</div><div class="trend-foot"><span>● Session attendance</span><span>Consistent care makes a difference.</span></div></div></section></div><div class="side-column"><section class="card"><div class="card-head"><h2>Care comes first</h2><span class="pill amber">${openAlerts().length} open</span></div><div class="attention">${openAlerts().slice(0,3).map(a=>`<div class="alert-item"><span class="alert-symbol ${a.level}">!</span><div><h3>${esc(a.reason)}</h3><p>${a.code} · ${esc(a.time)}</p><button class="btn ghost" data-alert="${a.id}">Review ${a.level==='red'?'urgently':'check-in'} →</button></div></div>`).join('')||'<p>All follow-ups are up to date.</p>'}</div></section><section class="card ladder-banner"><div class="eyebrow">THE NEXT CHAPTER</div><h2>Recovery opens doors.</h2><p>From consistent progress to skills, confidence and new opportunities.</p><a class="btn secondary" href="#ladder">Explore Pora Ladder →</a><div class="stairs" aria-hidden="true"><i></i><i></i><i></i><i></i></div></section></div></div>`}
function participants(){return top('People, not numbers.','A confidential caseload, with the next step always in view.',btn(svg('plus')+' Enrol participant','enrol',''))+`<section class="card"><div class="card-head"><h2>Your participants <span class="pill neutral">${db.participants.length}</span></h2></div><div class="filters"><input id="search" type="search" aria-label="Search participants" placeholder="Search nickname or participant code" value="${esc(search)}"><select id="filter" aria-label="Filter status"><option value="all">All participants</option><option value="active" ${filter==='active'?'selected':''}>Active</option><option value="withdrawn" ${filter==='withdrawn'?'selected':''}>Withdrawn</option></select></div>${table(['PARTICIPANT','PHASE','STREAK','STATUS',''],participantRows(db.participants.filter(p=>(filter==='all'||p.status===filter)&&(p.name+' '+p.code).toLowerCase().includes(search.toLowerCase()))))}</section>`}
function sessions(){return top('Make this session count.','Supervised recording, target-aware evaluation and transparent rewards.')+`<div class="notice">Sandbox sessions only. Capture the test card alone; never include a face or identity document. Photos are validated locally and are not uploaded or retained in this demo.</div><section class="card"><div class="card-head"><h2>Scheduled today</h2><span class="pill neutral">09:00–12:00 · UTC+2</span></div>${table(['PARTICIPANT','TIME','STREAK','STATUS',''],participantRows(active(),true))}</section><section class="card"><div class="card-head"><h2>Recent session records</h2></div>${table(['CODE','OUTCOME','REWARD','CONFIG','RECORDED'],db.sessions.map(s=>`<tr><td>${s.code}</td><td><span class="pill ${s.outcome==='negative'?'':s.outcome==='excused'?'neutral':'amber'}">${esc(s.outcome)}</span></td><td>${money(s.amount)}</td><td>v${s.configVersion}</td><td>${esc(s.date)}</td></tr>`))}</section>`}
function alerts(){return top('Listen. Reach out. Follow through.','Human-reviewed care alerts. Nothing is resolved automatically.')+`<div class="tabs">${['all','red','amber','resolved'].map(k=>`<button class="tab ${filter===k?'active':''}" data-filter="${k}">${k==='all'?'All alerts':k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><div class="notice">Red alerts need supervisor review and acknowledgement within 30 minutes during operating hours. This sandbox does not send SMS, push notifications or emergency requests.</div><section class="card">${table(['PRIORITY','PARTICIPANT','REASON','STATUS',''],db.alerts.filter(a=>filter==='all'||filter==='resolved'&&a.status==='resolved'||a.level===filter).map(a=>`<tr><td><span class="pill ${a.level}">${a.level.toUpperCase()}</span></td><td>${a.code}</td><td>${esc(a.reason)}</td><td>${esc(a.status)}</td><td><button class="btn ghost" data-alert="${a.id}">Review →</button></td></tr>`))}</section><section class="card"><div class="card-head"><div><h2>Structured check-in</h2><small>Try a participant check-in and create a human review task.</small></div>${btn('Add demo check-in','checkin')}</div></section>`}
function rewards(){const total=db.ledger.reduce((n,l)=>n+l.amount,0);return top('Progress deserves recognition.','An append-only demo ledger, with each reward linked to its session.')+`<div class="stats">${stat('Rewards earned',money(total),'This device’s sandbox ledger','rewards')}${stat('Pending sandbox payouts',db.ledger.filter(l=>l.status==='queued').length,'No money will be transferred','sessions')}${stat('Reward configuration','v'+db.config.version,'Version attached to every entry','settings')}${stat('Maximum per programme',money(Array.from({length:24}).reduce((a,_,i)=>a+Math.min(db.config.base+db.config.step*i,db.config.cap)+((i+1)%db.config.bonusEvery===0?db.config.bonus:0),0)),'24 negative sessions · excludes SRHR','reports')}</div><section class="card"><div class="card-head"><h2>Reward ledger</h2>${btn('Export sandbox ledger','export-ledger')}</div>${table(['PARTICIPANT','TYPE','AMOUNT','STREAK','PAYOUT',''],db.ledger.map(l=>`<tr><td>${l.code}</td><td>${esc(l.type)}</td><td class="ledger-amount">${money(l.amount)}</td><td>${l.streak}</td><td><span class="pill ${l.status==='queued'?'amber':''}">${l.status==='confirmed'?'Sandbox confirmed':'Sandbox queued'}</span></td><td>${l.status==='queued'?`<button class="btn ghost" data-payout="${l.id}">Simulate confirmation →</button>`:''}</td></tr>`))}</section><div class="notice">EcoCash, OneMoney and airtime providers are not connected. Sandbox confirmations only update this demo ledger.</div>`}
function ladder(){return top('A new chapter starts here.','Skills and opportunities unlocked by 16 consecutive drug-free sessions.')+`<section class="card ladder-banner"><div class="eyebrow">THE PORA LADDER</div><h2>Show up. Build confidence. Move forward.</h2><p>Eight consistent weeks open a pathway to learning and work. Coaches record completed activities and skills credits.</p><div class="stairs" aria-hidden="true"><i></i><i></i><i></i><i></i></div></section><div class="report-grid">${active().map(p=>`<section class="card"><div class="card-head">${person(p)}<span class="pill ${p.streak>=16?'':'neutral'}">${p.streak>=16?'Unlocked':'In progress'}</span></div><div class="activities"><div class="row" style="justify-content:space-between"><span>${Math.min(p.streak,16)} / 16 sessions</span><b>${p.credits} credits</b></div><div class="progress"><i style="width:${Math.min(p.streak/16*100,100)}%"></i></div>${p.streak>=16?`<button class="btn secondary" data-activity="${p.code}">Record completed activity</button>`:`<small>${16-p.streak} consecutive sessions to the next chapter.</small>`}${db.activities.filter(a=>a.code===p.code).map(a=>`<div class="activity"><span>${esc(a.title)}</span><b>+${a.credits} credits</b></div>`).join('')}</div></section>`).join('')}</div>`}
function reports(){const negative=db.sessions.filter(s=>s.outcome==='negative').length,total=db.sessions.filter(s=>s.outcome!=='excused').length,eligible=active().length>=5;return top('See the programme. Protect the person.','Aggregate reporting with small-group privacy safeguards.',btn('Export aggregate report','export-report'))+`<div class="notice good-notice">Aggregate views contain no names, codes, results or check-in content. Metrics for groups smaller than five are suppressed.</div><div class="stats">${stat('Enrolled participants',db.participants.length>=5?db.participants.length:'Suppressed','Minimum group size: 5','participants')}${stat('Ladder unlock rate',eligible?Math.round(active().filter(p=>p.streak>=16).length/active().length*100)+'%':'Suppressed','Among active demo participants','ladder')}${stat('Recorded negative rate',total>=5?Math.round(negative/total*100)+'%':'Suppressed','Requires at least 5 recorded sessions','sessions')}${stat('Sandbox reward spend',db.ledger.length>=5?money(db.ledger.reduce((n,l)=>n+l.amount,0)):'Suppressed','Requires at least 5 reward records','rewards')}</div><section class="card"><div class="card-head"><h2>Pilot readiness</h2><span class="pill amber">Pre-launch</span></div><div class="metric-list">${[['Clinical protocol approval','Required'],['Crisis contacts verified per site','Required'],['Staff MFA and API-enforced roles','Not connected'],['Payment provider sandbox','Not connected'],['Multilingual triage evaluation','Required'],['Independent security review','Required']].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div></section>`}
function settings(){return top('A programme with clear rules.','Versioned reward configuration and a transparent record of changes.')+`<div class="report-grid"><section class="card"><div class="card-head"><h2>Reward schedule</h2><span class="pill neutral">Version ${db.config.version}</span></div><form id="config-form" class="setting"><div class="form-grid">${[['base','Base reward (USD)'],['step','Increase per session (USD)'],['cap','Reward cap (USD)'],['bonus','Streak bonus (USD)']].map(([k,l])=>`<label>${l}<input name="${k}" type="number" min="0.01" max="100" step="0.01" value="${db.config[k]/100}" required></label>`).join('')}<label>Bonus every (sessions)<input name="bonusEvery" type="number" min="1" max="24" value="${db.config.bonusEvery}" required></label><label>Recovery negatives before jump<input name="recoveryNegatives" type="number" min="1" max="10" value="${db.config.recoveryNegatives}" required></label></div><p><small>New settings apply only to future sessions. Existing ledger entries retain their configuration version.</small></p><button class="btn">Save new demo version</button></form></section><section class="card"><div class="card-head"><h2>Channels & integrations</h2></div><div class="setting">${[['WhatsApp Business','Verified business and dedicated number needed'],['USSD & SMS','Zimbabwean aggregator needed'],['Airtime & mobile money','Disbursement provider needed'],['Voice check-ins & AI','Transcription and validated classifier needed'],['Staff authentication','Password, TOTP and API roles needed']].map(([a,b])=>`<div class="integration"><div><h3>${a}</h3><p>${b}</p></div><span class="pill neutral">Not connected</span></div>`).join('')}</div></section></div><section class="card"><div class="card-head"><h2>Demo audit trail</h2>${btn('Reset sandbox data','reset')}</div>${table(['TIME (UTC)','ACTION','REFERENCE'],db.audit.slice(0,20).map(a=>`<tr><td>${esc(a.at)}</td><td>${esc(a.action)}</td><td>${esc(a.code)}</td></tr>`))}</section>`}
function modal(title,body){$('#dialog-content').innerHTML=`<div class="dialog-top"><h2>${title}</h2><button class="close" aria-label="Close dialog" data-action="close">×</button></div>${body}`;$('#modal').showModal();bindModal()}
function enrol(){modal('A first step forward',`<div class="notice">Demo enrolment. Use a fictional nickname only. Do not enter personal contact details or real health information.</div><form id="enrol-form"><div class="form-grid"><label>Nickname<input name="name" maxlength="30" required></label><label>Age<input type="number" name="age" min="18" max="35" required></label><label>Preferred language<select name="language"><option>English</option><option>chiShona</option><option>isiNdebele</option></select></label><label>Payout preference<select name="payout"><option value="airtime">Airtime</option><option value="mobile_money">Mobile money</option></select></label></div><label><input type="checkbox" name="resident" required>Ordinarily resident in Zimbabwe</label><label><input type="checkbox" name="eligible" required>Uses at least one screened substance and is not in acute crisis</label><label><input type="checkbox" name="consent" required>Fictional participant accepts programme processing consent v1.0; participation is voluntary and may be withdrawn.</label><label><input type="checkbox" name="research">Separate optional research consent</label><label><input type="checkbox" name="baseline" required>In-person intake and unrewarded baseline completed (simulation)</label><div class="form-actions"><button class="btn secondary" type="button" data-action="close">Cancel</button><button class="btn">Create demo participant</button></div></form>`);$('#enrol-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),max=Math.max(...db.participants.map(p=>+p.code.split('-')[2]));const p={code:'PR-HRE-'+String(max+1).padStart(4,'0'),name:f.get('name').trim(),language:f.get('language'),payout:f.get('payout'),phase:'A',week:1,targets:['MET','AMP'],level:1,streak:0,preResetLevel:null,negSinceReset:0,status:'active',credits:0,consent:true,research:f.has('research'),created:new Date().toISOString(),next:'11:30'};if(!p.name)return;db.participants.push(p);$('#modal').close();persist('processing_consent_v1_and_enrolment',p.code);toast(p.code+' enrolled. Baseline is unrewarded.')}}
function record(code){const p=pBy(code);modal('Record a supervised session',`<p><b>${esc(p.name)}</b> · ${p.code}</p><div class="notice good-notice">Phase ${p.phase} · Target panels: ${p.targets.join(', ')}. Only target panels determine rewards. A positive non-target panel remains visible to the coach.</div><form id="test-form"><label>Attendance<select id="attendance" name="attendance"><option value="present">Present — record panels</option><option value="missed">Missed — reset streak</option><option value="excused">Excused — preserve streak</option></select></label><div id="test-fields"><div class="panel-grid">${['MET','AMP','THC','OPI','BZO'].map(t=>`<label>${t}${p.targets.includes(t)?' · target':''}<select name="${t}" required><option value="">Select result</option><option value="negative">Negative</option><option value="positive">Positive</option><option value="invalid">Invalid (not retested)</option></select></label>`).join('')}</div><label><input type="checkbox" name="temperature" required>Temperature confirmed between 32°C and 38°C</label><label><input type="checkbox" name="adulterated">Adulteration detected</label><label>Test card photo — no faces or IDs<input type="file" id="photo" accept="image/jpeg,image/png,image/webp" required></label><small>Photo checked locally, then discarded. This demo cannot support photographic audits.</small></div><label id="reason-field" hidden>Reason for excused absence<textarea name="reason" maxlength="200"></textarea></label><div id="reward-preview" class="reward-preview">Complete the panel results to preview the reward.</div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button class="btn">Save sandbox session</button></div></form>`);const form=$('#test-form');function preview(){const f=new FormData(form),a=f.get('attendance'),panels=Object.fromEntries(['MET','AMP','THC','OPI','BZO'].map(t=>[t,f.get(t)]));const outcome=a==='present'?outcomeFor(panels,p.targets,f.has('temperature'),f.has('adulterated')):a;const r=evaluate(p,outcome,db.config);$('#reward-preview').textContent=`${outcome==='negative'?'Reward eligible':'Outcome: '+outcome} · ${money(r.amount+r.bonus)} · Streak after session: ${r.state.streak}${r.bonus?' · Includes '+money(r.bonus)+' streak bonus':''}`;return{f,panels,outcome,r}}form.onchange=()=>{const a=$('#attendance').value;$('#test-fields').hidden=a!=='present';$('#test-fields').querySelectorAll('input,select').forEach(el=>el.disabled=a!=='present');$('#reason-field').hidden=a!=='excused';form.elements.reason.required=a==='excused';preview()};form.onsubmit=async e=>{e.preventDefault();if(db.sessions.some(s=>s.code===code&&s.date===new Date().toISOString().slice(0,10))){toast('A session has already been recorded today.');return}const{f,panels,outcome,r}=preview();if(f.get('attendance')==='present'){const file=$('#photo').files[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose a JPEG, PNG or WebP photo under 10 MB.');return}try{const bitmap=await createImageBitmap(file);bitmap.close()}catch{toast('This file is not a readable image.');return}}if(outcome==='excused'&&db.sessions.filter(s=>s.code===code&&s.outcome==='excused').length>=2){toast('Two excused absences recorded. Supervisor approval is required for another.');return}Object.assign(p,r.state);const session={id:crypto.randomUUID(),code,date:new Date().toISOString().slice(0,10),outcome,panels,targets:[...p.targets],amount:r.amount+r.bonus,configVersion:db.config.version,reason:esc(f.get('reason')||'')};db.sessions.unshift(session);for(const[type,amount]of[['Session reward',r.amount],['Streak bonus',r.bonus]])if(amount)db.ledger.unshift({id:crypto.randomUUID(),sessionId:session.id,code,type,amount,streak:p.streak,configVersion:db.config.version,status:'queued',method:p.payout});if(['positive','missed','invalid'].includes(outcome))db.alerts.unshift({id:crypto.randomUUID(),code,level:'amber',reason:outcome==='missed'?'Missed session follow-up':'Session follow-up',summary:'A supportive coach conversation is needed. Agree the next step without judgement.',status:'open',time:'Just now',notes:''});$('#modal').close();persist('session_saved_'+outcome,code);toast(outcome==='negative'?`Session saved. ${money(session.amount)} earned; sandbox payout queued.`:'Session recorded. Follow-up and progress updated.')}}
function profile(code){const p=pBy(code);modal('Participant progress',`<div class="profile-header">${person(p)}</div><div class="detail-grid"><div><small>Phase</small><b>${p.phase} · Week ${p.week}</b></div><div><small>Language</small><b>${esc(p.language)}</b></div><div><small>Streak</small><b>${p.streak} sessions</b></div><div><small>Target panels</small><b>${p.targets.join(', ')}</b></div><div><small>Next reward</small><b>${money(evaluate(p,'negative',db.config).amount)}</b></div><div><small>Status</small><b>${esc(p.status)}</b></div></div><h3>Coach notes</h3>${db.notes.filter(n=>n.code===code).map(n=>`<p>${esc(n.body)}</p>`).join('')||'<p><small>No notes yet.</small></p>'}<form id="note-form"><label>Add a fictional care note<textarea name="body" required maxlength="500"></textarea></label><button class="btn secondary">Save note</button></form><div class="form-actions">${p.status==='active'?`<button class="btn danger" id="withdraw">Withdraw demo participant</button>`:''}</div>`);$('#note-form').onsubmit=e=>{e.preventDefault();db.notes.unshift({code,body:new FormData(e.target).get('body'),at:new Date().toISOString()});persist('coach_note_added',code);$('#modal').close();toast('Coach note recorded.')};if($('#withdraw'))$('#withdraw').onclick=()=>{p.status='withdrawn';persist('withdrawn',code);$('#modal').close();toast('Demo participant withdrawn.')}}
function alertReview(id){const a=db.alerts.find(a=>a.id===id);modal('Care alert · '+a.level.toUpperCase(),`<span class="pill ${a.level}">${esc(a.status)}</span><p><b>${a.code} · ${esc(a.reason)}</b></p><p>${esc(a.summary)}</p>${a.level==='red'?'<div class="notice">Urgent supervisor review required. Verify the participant’s immediate safety and use the site’s approved crisis protocol. No crisis contacts have been configured in this sandbox.</div>':''}<label>Human review / follow-up note<textarea id="alert-note" maxlength="500">${esc(a.notes)}</textarea></label><div class="form-actions">${a.status==='open'?'<button class="btn secondary" id="ack">Acknowledge</button>':''}${a.status!=='resolved'?'<button class="btn" id="resolve">Resolve with review note</button>':''}</div>`);if($('#ack'))$('#ack').onclick=()=>{a.status='acknowledged';a.notes=$('#alert-note').value;persist('alert_acknowledged',a.code);$('#modal').close();toast('Alert acknowledged; follow-up remains open.')};if($('#resolve'))$('#resolve').onclick=()=>{if(!$('#alert-note').value.trim()){toast('Add a human review note before resolving.');return}a.status='resolved';a.notes=$('#alert-note').value;persist('alert_resolved_human_review',a.code);$('#modal').close();toast('Alert resolved with a review note.')}}
function checkin(){modal('Structured demo check-in',`<form id="checkin-form"><label>Demo participant<select name="code">${active().map(p=>`<option value="${p.code}">${esc(p.name)} · ${p.code}</option>`).join('')}</select></label><div class="form-grid"><label>Mood (1 = low, 5 = good)<input name="mood" type="number" min="1" max="5" value="3" required></label><label>Cravings (1 = low, 5 = strong)<input name="craving" type="number" min="1" max="5" value="2" required></label></div><label><input name="use" type="checkbox">Use reported this week</label><label><input name="contact" type="checkbox">Wants coach contact</label><label><input name="help" type="checkbox">“Get help now” selected — urgent supervisor review</label><div class="notice">Structured rules only; no AI classification, transcription or clinical assessment is performed.</div><button class="btn">Submit demo check-in</button></form>`);$('#checkin-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),level=f.has('help')?'red':f.has('use')||f.has('contact')||+f.get('craving')>=4?'amber':'green',code=f.get('code');db.checkins.push({code,mood:+f.get('mood'),craving:+f.get('craving'),level});if(level!=='green')db.alerts.unshift({id:crypto.randomUUID(),code,level,reason:level==='red'?'Urgent help requested':'Check-in follow-up',summary:`Mood ${f.get('mood')}/5; cravings ${f.get('craving')}/5. ${f.has('contact')?'Coach contact requested.':''} Human review required.`,status:'open',time:'Just now',notes:''});$('#modal').close();persist('structured_checkin_'+level,code);toast(level==='green'?'Check-in recorded for weekly review.':'Care alert created for human review.')}}
function activity(code){modal('Record a completed activity',`<form id="activity-form"><label>Activity title<input name="title" required maxlength="100" placeholder="e.g. Digital skills workshop"></label><label>Verified skills credits<input type="number" name="credits" min="1" max="100" required value="10"></label><label><input type="checkbox" required>Coach verified completion</label><button class="btn">Record credits</button></form>`);$('#activity-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);db.activities.push({code,title:f.get('title'),credits:+f.get('credits')});pBy(code).credits+=+f.get('credits');$('#modal').close();persist('ladder_activity_verified',code);toast('Completed activity and skills credits recorded.')}}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function actions(action){if(action==='close')$('#modal').close();if(action==='enrol')enrol();if(action==='checkin')checkin();if(action==='export-ledger')download('pora-sandbox-ledger.json',db.ledger);if(action==='export-report')download('pora-aggregate-report.json',{generated:new Date().toISOString(),demo:true,enrolled:db.participants.length>=5?db.participants.length:null,ladderUnlockRate:active().length>=5?active().filter(p=>p.streak>=16).length/active().length:null,smallGroupsSuppressed:true});if(action==='reset')modal('Reset this sandbox?',`<p>This clears the fictional records stored on this device and restores the sample caseload.</p><div class="form-actions">${btn('Cancel','close')}${btn('Reset demo data','confirm-reset','danger')}</div>`);if(action==='confirm-reset'){db=seed();$('#modal').close();persist('sandbox_reset');toast('Sample caseload restored.')}}
function bindModal(){$('#modal').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions(b.dataset.action));$('#modal').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>profile(b.dataset.profile))}
function bind(){document.querySelectorAll('main [data-action]').forEach(b=>b.onclick=()=>actions(b.dataset.action));document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>record(b.dataset.test));document.querySelectorAll('main [data-profile]').forEach(b=>b.onclick=()=>profile(b.dataset.profile));document.querySelectorAll('[data-alert]').forEach(b=>b.onclick=()=>alertReview(b.dataset.alert));document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>activity(b.dataset.activity));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-payout]').forEach(b=>b.onclick=()=>{const l=db.ledger.find(l=>l.id===b.dataset.payout);if(l.status==='confirmed')return;l.status='confirmed';persist('sandbox_payout_confirmed',l.code);toast('Sandbox confirmation recorded. No money transferred.')});if($('#search'))$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render()};if($('#config-form'))$('#config-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),cfg={...db.config,version:db.config.version+1};for(const k of['base','step','cap','bonus'])cfg[k]=Math.round(+f.get(k)*100);cfg.bonusEvery=+f.get('bonusEvery');cfg.recoveryNegatives=+f.get('recoveryNegatives');if(cfg.base>cfg.cap){toast('The cap must be at least the base reward.');return}db.config=cfg;persist('reward_config_version_'+cfg.version);toast('New configuration applies to future sessions.')}}
window.addEventListener('hashchange',()=>{filter='all';search='';$('.sidebar').classList.remove('open');render()});$('#mobile').onclick=()=>$('.sidebar').classList.toggle('open');$('#help').onclick=()=>modal('About this Pora workspace','<p>A functional, device-local prototype based on your Pora development specification.</p><p>Enrolment, sessions, reward calculation, alerts, check-ins, Ladder activities and exports work with fictional data. Records persist in this browser only.</p><p>Staff authentication, server-side access controls, encrypted cloud storage, messaging, live payouts, voice transcription, clinical triage and dispute replay remain to be integrated and validated before a pilot.</p><p>The supplied logo could not be downloaded in this environment; the current mark is a temporary teal wordmark.</p>');render();
